"""
Execution-grounded verification of agent-authored workspaces.

This module implements the ExecutionHarness which verifies code by actually
running it (parsing, installing, importing, testing) rather than relying on
textual analysis or file counts.
"""

import ast
import os
import sys
import subprocess
import tempfile
import shutil
import time
import tomllib
import re
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple, Iterable

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Dependency on artifacts module (assumed available in environment)
try:
    from hae.evaluation.artifacts import (
        filter_bundle,
        is_generated_path,
        is_malformed_path,
        sanitize_path,
        partition_bundle,
        count_source_files
    )
except ImportError:
    # Fallback implementations if artifacts module is not yet available or import fails
    # These mimic the behavior described in the artifacts.py spec
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path != path.strip():
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        path = path.strip()
        path = path.replace('*', '').replace('`', '')
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in bundle:
            if any(path.endswith(s) for s in suffixes):
                count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed_count = sum(1 for g in evaluated if g.passed)
        return passed_count / len(evaluated)

    def summary(self) -> str:
        lines = [
            f"Verification Report ({self.source})",
            f"Authored Files: {self.authored_files} (Python: {self.python_files})",
            f"Score Penalty: {self.score_penalty:.2f}",
            f"Pass Rate: {self.pass_rate:.2%}",
            "-" * 40
        ]
        for g in self.gates:
            status_icon = "✓" if g.passed else ("✗" if g.status == FAILED else "-")
            lines.append(f"[{status_icon}] {g.name:10} : {g.status:8} ({g.method})")
            if g.detail:
                lines.append(f"    Detail: {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional filename hint
    # Pattern: ```[language] [filename]\n...content...\n```
    # We look for blocks that might contain a filename hint in the info string
    pattern = r"```(?:\w+)?\s*([^\n]*)\n(.*?)\n```"
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    for info, content in matches:
        # Try to extract a filename from the info string
        # Common patterns: "python src/main.py", "src/main.py", "main.py"
        parts = info.strip().split()
        filename = None
        for part in parts:
            if '.' in part and not part.startswith('-'):
                # Heuristic: if it looks like a filename, take it
                # Avoid taking language tags like 'python' unless they have dots (unlikely)
                if not part.isalpha():
                    filename = part
                    break

        if filename:
            # Sanitize the filename
            clean_filename = sanitize_path(filename)
            if clean_filename:
                bundle[clean_filename] = content

    return bundle


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict-like
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
            elif isinstance(workspace, dict):
                bundle = workspace
            elif hasattr(workspace, 'files'):
                bundle = workspace.files

        # If bundle is empty, try extracting from deliverable text
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        if not bundle:
            # Empty workspace
            return self._empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def _empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast_parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='packaging', detail='No packaging metadata found'),
            GateResult(name='smoke', status=FAILED, method='import', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest', detail='No test files found'),
            GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No telemetry usage found'),
        ]
        return VerificationReport(
            gates=gates,
            score_penalty=len(gates) * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source
        )

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed paths
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files_count = len(authored_bundle)
        python_files_count = count_source_files(authored_bundle, suffixes=('.py',))

        if authored_files_count == 0:
            return self._empty_report(source)

        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to temp dir
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory for files
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Filter out excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        authored_files_count = len(authored)
        python_files_count = count_source_files(authored, suffixes=('.py',))

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files_count,
            python_files=python_files_count,
            source=source
        )

    def _get_python_files(self, workdir: str, authored: Dict[str, str]) -> List[str]:
        """Returns list of relative paths to .py files in authored bundle."""
        return [p for p in authored if p.endswith('.py')]

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = 'ast_parse'
        py_files = self._get_python_files(workdir, authored)

        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method=method,
                detail='No Python files found',
                duration_s=time.time() - start_time
            )

        errors = []
        for rel_path in py_files:
            full_path = os.path.join(workdir, rel_path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{rel_path}: {e}")
            except Exception as e:
                errors.append(f"{rel_path}: {e}")

        duration = time.time() - start_time
        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method=method,
                detail='Syntax errors found: ' + '; '.join(errors[:5]),
                duration_s=duration,
                evidence={'errors': errors}
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method=method,
            detail=f"All {len(py_files)} Python files parsed successfully",
            duration_s=duration
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = 'packaging'

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(
                name='build',
                status=FAILED,
                method=method,
                detail='No packaging metadata (pyproject.toml, setup.py, or setup.cfg) found',
                duration_s=time.time() - start_time
            )

        # Validate pyproject.toml if present
        if has_pyproject:
            pyproject_path = os.path.join(workdir, 'pyproject.toml')
            try:
                with open(pyproject_path, 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(key in data for key in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method=method,
                        detail='pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool])',
                        duration_s=time.time() - start_time
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method=method,
                    detail=f'pyproject.toml is invalid: {e}',
                    duration_s=time.time() - start_time
                )

        # Attempt pip install
        try:
            # Check if pip is available
            subprocess.run(
                [self.python_executable, '-m', 'pip', '--version'],
                capture_output=True,
                timeout=10
            )
        except Exception:
            return GateResult(
                name='build',
                status=SKIPPED,
                method=method,
                detail='pip not available or failed to start',
                duration_s=time.time() - start_time
            )

        try:
            # Run pip install -e . --no-deps --no-build-isolation
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start_time

            if result.returncode == 0:
                return GateResult(
                    name='build',
                    status=PASSED,
                    method=method,
                    detail='Package installed successfully',
                    duration_s=duration
                )
            else:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method=method,
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=duration,
                    evidence={'stderr': result.stderr, 'stdout': result.stdout}
                )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method=method,
                detail='pip install timed out',
                duration_s=time.time() - start_time
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method=method,
                detail=f'pip install error: {e}',
                duration_s=time.time() - start_time
            )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = 'import'

        # Find non-test authored modules
        # Exclude test files and __init__.py? Spec says "Non-test authored modules"
        # Usually smoke tests import the main package modules.
        # We'll try to import all .py files that are not tests.

        py_files = self._get_python_files(workdir, authored)
        non_test_modules = []

        for rel_path in py_files:
            basename = os.path.basename(rel_path)
            if 'test' in basename.lower():
                continue
            if basename == '__init__.py':
                continue

            # Convert path to module name
            # e.g., src/foo/bar.py -> foo.bar (if src is on path)
            # We will add workdir and workdir/src to PYTHONPATH

            # Determine module name relative to workdir or src
            # If file is in src/, module is relative to src/
            # If file is in root/, module is relative to root/

            parts = rel_path.split(os.sep)
            if parts[0] == 'src':
                module_parts = parts[1:]
            else:
                module_parts = parts

            if module_parts[-1].endswith('.py'):
                module_parts[-1] = module_parts[-1][:-3]

            module_name = '.'.join(module_parts)
            non_test_modules.append((rel_path, module_name))

        if not non_test_modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method=method,
                detail='No importable non-test modules found',
                duration_s=time.time() - start_time
            )

        # Prepare environment
        env = os.environ.copy()
        python_path = env.get('PYTHONPATH', '')
        new_paths = [workdir, os.path.join(workdir, 'src')]
        if python_path:
            env['PYTHONPATH'] = os.pathsep.join(new_paths + [python_path])
        else:
            env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # Try importing each module in a subprocess
        import_errors = []
        module_not_found_errors = []

        for rel_path, module_name in non_test_modules:
            script = f"import {module_name}"
            try:
                result = subprocess.run(
                    [self.python_executable, '-c', script],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=10
                )

                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package
                        # If the module itself is not found, it's a failure.
                        # If a dependency is not found, it's skipped.
                        # We need to distinguish.
                        # If the error is "No module named 'module_name'", it's a failure.
                        # If it's "No module named 'opentelemetry'", it's skipped.

                        # Simple heuristic: if the module name we tried to import is in the error, it's a failure.
                        # Otherwise, assume it's a dependency issue.
                        if f"No module named '{module_name}'" in stderr or f"No module named \"{module_name}\"" in stderr:
                            import_errors.append(f"{module_name}: {stderr}")
                        else:
                            module_not_found_errors.append(f"{module_name}: {stderr}")
                    else:
                        import_errors.append(f"{module_name}: {stderr}")
            except Exception as e:
                import_errors.append(f"{module_name}: {e}")

        duration = time.time() - start_time

        if import_errors:
            return GateResult(
                name='smoke',
                status=FAILED,
                method=method,
                detail='Import errors: ' + '; '.join(import_errors[:5]),
                duration_s=duration,
                evidence={'errors': import_errors}
            )

        if module_not_found_errors:
            return GateResult(
                name='smoke',
                status=SKIPPED,
                method=method,
                detail='Third-party dependencies missing: ' + '; '.join(module_not_found_errors[:5]),
                duration_s=duration,
                evidence={'missing_deps': module_not_found_errors}
            )

        return GateResult(
            name='smoke',
            status=PASSED,
            method=method,
            detail=f"All {len(non_test_modules)} modules imported successfully",
            duration_s=duration
        )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = 'pytest'

        # Find test files
        test_files = []
        for rel_path in authored:
            basename = os.path.basename(rel_path)
            if 'test' in basename.lower() and rel_path.endswith('.py'):
                test_files.append(rel_path)

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method=method,
                detail='No test files found',
                duration_s=time.time() - start_time
            )

        # Prepare environment
        env = os.environ.copy()
        python_path = env.get('PYTHONPATH', '')
        new_paths = [workdir, os.path.join(workdir, 'src')]
        if python_path:
            env['PYTHONPATH'] = os.pathsep.join(new_paths + [python_path])
        else:
            env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # Check if pytest is available
        try:
            subprocess.run(
                [self.python_executable, '-m', 'pytest', '--version'],
                capture_output=True,
                timeout=10
            )
            use_pytest = True
        except Exception:
            use_pytest = False

        if use_pytest:
            method = 'pytest'
            try:
                # Run pytest on the test files
                # We pass the relative paths to pytest
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest'] + test_files,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                duration = time.time() - start_time

                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method=method,
                        detail='All tests passed',
                        duration_s=duration
                    )
                else:
                    # Check if failure is due to ModuleNotFoundError
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                        # If tests couldn't run because of missing deps, skip
                        # But if they ran and failed, it's failed.
                        # Pytest usually reports collection errors.
                        # If "no tests ran" or collection error due to import, skip.
                        if "no tests ran" in result.stdout or "error" in result.stderr.lower():
                             # Heuristic: if it's an import error during collection
                             if "ModuleNotFoundError" in result.stderr:
                                 return GateResult(
                                    name='tests',
                                    status=SKIPPED,
                                    method=method,
                                    detail='Tests skipped due to missing dependencies',
                                    duration_s=duration,
                                    evidence={'stderr': result.stderr}
                                 )

                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method=method,
                        detail='Tests failed',
                        duration_s=duration,
                        evidence={'stdout': result.stdout, 'stderr': result.stderr}
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method=method,
                    detail='Tests timed out',
                    duration_s=time.time() - start_time
                )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method=method,
                    detail=f'Pytest execution error: {e}',
                    duration_s=time.time() - start_time
                )
        else:
            # Stdlib fallback
            method = 'unittest_fallback'
            # Run a subprocess that imports each test file and collects/executes
            # bare def test_*() functions AND unittest.TestCase subclasses

            script = f'''
import sys
import os
import unittest
import importlib.util
import inspect

def run_tests(test_files):
    loader = unittest.TestLoader()
    suite = unittest.TestSuite()

    for test_file in test_files:
        try:
            # Import the module
            spec = importlib.util.spec_from_file_location('test_module', test_file)
            module = importlib.util.module_from_spec(spec)
            sys.modules['test_module'] = module
            spec.loader.exec_module(module)

            # Collect unittest.TestCase subclasses
